        } else if (statement == ST_IF) {
            unsigned int line;
            if (index == length || !ascii_letter(source[index])) {
                return BT_UNSUPPORTED_CONSTRUCT;
            }
            status = explicit_variable(source, length, &index, out,
                                       BVR_TYPE_INTEGER);
            if (status == BT_OK) {
                status = spaces(source, length, &index, out);
