            if (status != BT_OK) {
                return status;
            }
            if (!keyword_matches(source, length, index, "THEN", &count)) {
                return BT_UNSUPPORTED_CONSTRUCT;
            }
            index += count;
            status = emit(out, 0xebu);
            if (status == BT_OK) {
